/**
 * React context for Hyperswitch SDK
 */
import React, { createContext, useContext, ReactNode } from 'react';
import { Hyperswitch } from '@juspay-tech/hyperswitch-control-center-embed-core';

// Create context
const HyperswitchContext = createContext<Hyperswitch | null>(null);

// Props for provider component
interface HyperswitchProviderProps {
  hyperswitchInstance: Hyperswitch;
  children: ReactNode;
}

/**
 * Provider component to make Hyperswitch instance available throughout React component tree
 */
export function HyperswitchProvider({ hyperswitchInstance, children }: HyperswitchProviderProps) {
  return (
    <HyperswitchContext.Provider value={hyperswitchInstance}>
      {children}
    </HyperswitchContext.Provider>
  );
}

/**
 * Hook to access the Hyperswitch instance
 */
export function useHyperswitchInstance(): Hyperswitch {
  const context = useContext(HyperswitchContext);
  if (!context) {
    throw new Error('useHyperswitchInstance must be used within a HyperswitchProvider');
  }
  return context;
}

import * as React from 'react';
import { useRef, useEffect } from 'react';
import { useHyperswitchInstance } from './context';
import { ElementOptions } from '@juspay-tech/hyperswitch-control-center-embed-core';
import type { ConnectorConfigurationComponent } from '@juspay-tech/hyperswitch-control-center-embed-core';

interface ComponentProps extends ElementOptions {}

export const ConnectorConfiguration: React.FC<ComponentProps> = (props) => {
  const hyperswitchInstance = useHyperswitchInstance();
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const component = hyperswitchInstance.create('connectors', props) as ConnectorConfigurationComponent;
    component.mount(containerRef.current);

    return () => {
      component.destroy();
    };
  }, [hyperswitchInstance, props]);

  return <div ref={containerRef} />;
};

ConnectorConfiguration.displayName = 'ConnectorConfiguration';
